216	                break;
217	            default:
218	                return BigDecimal.ZERO;
219	        }
220	
221	        BigDecimal insurance = productsSubtotal.multiply(percentage);
222	        if (limit != null && insurance.compareTo(limit) > 0) {
223	            insurance = limit;
224	        }
225	
226	        return insurance;
227	    }
